        /// <item><description><c>SDL_PROP_TEXTURE_CREATE_GPU_TEXTURE_UV_NUMBER</c>: the <see cref="CSDL.GPU.GPUTexture">GPUTexture</see> associated with the UV plane of an NV12 texture, if you want to wrap an existing texture.</description></item>
        /// <item><description><c>SDL_PROP_TEXTURE_CREATE_GPU_TEXTURE_U_NUMBER</c>: the <see cref="CSDL.GPU.GPUTexture">GPUTexture</see> associated with the U plane of a YUV texture, if you want to wrap an existing texture.</description></item>
        /// <item><description><c>SDL_PROP_TEXTURE_CREATE_GPU_TEXTURE_V_NUMBER</c>: the <see cref="CSDL.GPU.GPUTexture">GPUTexture</see> associated with the V plane of a YUV texture, if you want to wrap an existing texture.</description></item>
        /// </list>
        /// </remarks>
        /// <param name="renderer">the rendering context.</param>
        /// <param name="props">the properties to use.</param>
        /// <returns>
