        /// <summary>
        /// <para>Force the rendering context to flush any pending commands and state.</para>
        /// </summary>
        /// <remarks>
        /// <para>You do not need to (and in fact, shouldn't) call this function unless you are planning to call into OpenGL/Direct3D/Metal/whatever directly, in addition to using an <c>SDL_Renderer</c>.</para>
        /// <para>This is for a very-specific case: if you are using SDL's render API, and you plan to make OpenGL/D3D/whatever calls in addition to SDL render API calls. If this applies, you should call this function between calls to SDL's render API and the low-level API you're using in cooperation.</para>
        /// <para>In all other cases, you can ignore this function.</para>
        /// <para>This call makes SDL flush any pending rendering work it was queueing up to do later in a single batch, and marks any internal cached state as invalid, so it'll prepare all its state again later, from scratch.</para>
        /// <para>This means you do not need to save state in your rendering code to protect the SDL renderer. However, there lots of arbitrary pieces of Direct3D and OpenGL state that can confuse things; you should use your best judgment and be prepared to make changes if specific state needs to be protected.</para>
        /// </remarks>
        /// <param name="renderer">the rendering context.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_FlushRenderer">SDL_FlushRenderer</seealso></SDLWiki>
        public static extern void FlushRenderer();

