        /// <summary>
        /// <para>Get the properties associated with a texture.</para>
        /// </summary>
        /// <remarks>
        /// <para>The following read-only properties are provided by SDL:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.TextureColorspaceNumber">TextureColorspaceNumber</see>: an <see cref="CSDL.Video.Colorspace">Colorspace</see> value describing the texture colorspace.</description></item>
        /// <item><description><see cref="CSDL.Props.TextureFormatNumber">TextureFormatNumber</see>: one of the enumerated values in <see cref="CSDL.Video.PixelFormat">PixelFormat</see>.</description></item>
        /// <item><description><see cref="CSDL.Props.TextureAccessNumber">TextureAccessNumber</see>: one of the enumerated values in <see cref="CSDL.Video.TextureAccess">TextureAccess</see>.</description></item>
        /// <item><description><see cref="CSDL.Props.TextureWidthNumber">TextureWidthNumber</see>: the width of the texture in pixels.</description></item>
        /// <item><description><see cref="CSDL.Props.TextureHeightNumber">TextureHeightNumber</see>: the height of the texture in pixels.</description></item>
        /// <item><description><see cref="CSDL.Props.TextureSdrWhitePointFloat">TextureSdrWhitePointFloat</see>: for HDR10 and floating point textures, this defines the value of 100% diffuse white, with higher values being displayed in the High Dynamic Range headroom. This defaults to 100 for HDR10 textures and 1.0 for other textures.</description></item>
        /// <item><description><see cref="CSDL.Props.TextureHDRHeadroomFloat">TextureHDRHeadroomFloat</see>: for HDR10 and floating point textures, this defines the maximum dynamic range used by the content, in terms of the SDR white point. If this is defined, any values outside the range supported by the display will be scaled into the available HDR headroom, otherwise they are clipped. This defaults to 1.0 for SDR textures, 4.0 for HDR10 textures, and no default for floating point textures.</description></item>
        /// </list>
        /// <para>With the direct3d11 renderer:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.TextureD3D11TexturePointer">TextureD3D11TexturePointer</see>: the ID3D11Texture2D associated with the texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureD3D11TextureUPointer">TextureD3D11TextureUPointer</see>: the ID3D11Texture2D associated with the U plane of a YUV texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureD3D11TextureVPointer">TextureD3D11TextureVPointer</see>: the ID3D11Texture2D associated with the V plane of a YUV texture</description></item>
        /// </list>
        /// <para>With the direct3d12 renderer:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.TextureD3D12TexturePointer">TextureD3D12TexturePointer</see>: the ID3D12Resource associated with the texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureD3D12TextureUPointer">TextureD3D12TextureUPointer</see>: the ID3D12Resource associated with the U plane of a YUV texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureD3D12TextureVPointer">TextureD3D12TextureVPointer</see>: the ID3D12Resource associated with the V plane of a YUV texture</description></item>
        /// </list>
        /// <para>With the metal renderer:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.TextureMetalTexturePointer">TextureMetalTexturePointer</see>: the MTLTexture associated with the texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureMetalTextureUvPointer">TextureMetalTextureUvPointer</see>: the MTLTexture associated with the UV plane of an NV12 texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureMetalTextureUPointer">TextureMetalTextureUPointer</see>: the MTLTexture associated with the U plane of a YUV texture style texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureMetalTextureVPointer">TextureMetalTextureVPointer</see>: the MTLTexture associated with the V plane of a YUV texture</description></item>
        /// </list>
        /// <para>With the vulkan renderer:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.TextureVulkanTextureNumber">TextureVulkanTextureNumber</see>: the VkImage associated with the texture</description></item>
        /// </list>
        /// <para>With the opengl renderer:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.TextureOpenglTextureNumber">TextureOpenglTextureNumber</see>: the GLuint texture associated with the texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOpenglTextureUvNumber">TextureOpenglTextureUvNumber</see>: the GLuint texture associated with the UV plane of an NV12 texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOpenglTextureUNumber">TextureOpenglTextureUNumber</see>: the GLuint texture associated with the U plane of a YUV texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOpenglTextureVNumber">TextureOpenglTextureVNumber</see>: the GLuint texture associated with the V plane of a YUV texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOpenglTextureTargetNumber">TextureOpenglTextureTargetNumber</see>: the GLenum for the texture target (<c>GL_TEXTURE_2D</c>, <c>GL_TEXTURE_RECTANGLE_ARB</c>, etc)</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOpenglTexWFloat">TextureOpenglTexWFloat</see>: the texture coordinate width of the texture (0.0 - 1.0)</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOpenglTexHFloat">TextureOpenglTexHFloat</see>: the texture coordinate height of the texture (0.0 - 1.0)</description></item>
        /// </list>
        /// <para>With the opengles2 renderer:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.TextureOPENGLES2TextureNumber">TextureOPENGLES2TextureNumber</see>: the GLuint texture associated with the texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOPENGLES2TextureUvNumber">TextureOPENGLES2TextureUvNumber</see>: the GLuint texture associated with the UV plane of an NV12 texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOPENGLES2TextureUNumber">TextureOPENGLES2TextureUNumber</see>: the GLuint texture associated with the U plane of a YUV texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOPENGLES2TextureVNumber">TextureOPENGLES2TextureVNumber</see>: the GLuint texture associated with the V plane of a YUV texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureOPENGLES2TextureTargetNumber">TextureOPENGLES2TextureTargetNumber</see>: the GLenum for the texture target (<c>GL_TEXTURE_2D</c>, <c>GL_TEXTURE_EXTERNAL_OES</c>, etc)</description></item>
        /// </list>
        /// <para>With the gpu renderer:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.TextureGPUTexturePointer">TextureGPUTexturePointer</see>: the <see cref="CSDL.GPU.GPUTexture">GPUTexture</see> associated with the texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureGPUTextureUvPointer">TextureGPUTextureUvPointer</see>: the <see cref="CSDL.GPU.GPUTexture">GPUTexture</see> associated with the UV plane of an NV12 texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureGPUTextureUPointer">TextureGPUTextureUPointer</see>: the <see cref="CSDL.GPU.GPUTexture">GPUTexture</see> associated with the U plane of a YUV texture</description></item>
        /// <item><description><see cref="CSDL.Props.TextureGPUTextureVPointer">TextureGPUTextureVPointer</see>: the <see cref="CSDL.GPU.GPUTexture">GPUTexture</see> associated with the V plane of a YUV texture</description></item>
        /// </list>
        /// </remarks>
        /// <param name="texture">the texture to query.</param>
        /// <returns>
        /// <para>(<see cref="CSDL.PropertiesID">PropertiesID</see>) Returns a valid property ID on success or 0 on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_GetTextureProperties">SDL_GetTextureProperties</seealso></SDLWiki>
        public static extern void GetTextureProperties();

