        /// <summary>
        /// <para>Lock a portion of the texture for **write-only** pixel access.</para>
        /// </summary>
        /// <remarks>
        /// <para>As an optimization, the pixels made available for editing don't necessarily contain the old texture data. This is a write-only operation, and if you need to keep a copy of the texture data you should do that at the application level.</para>
        /// <para>You must use <see cref="CSDL.Video.Texture.Unlock">Unlock</see> to unlock the pixels and apply any changes.</para>
        /// </remarks>
        /// <param name="texture">the texture to lock for access, which was created with <see cref="CSDL.Video.TextureAccess.Streaming">Streaming</see>.</param>
        /// <param name="rect">an <see cref="CSDL.Video.Rect">Rect</see> structure representing the area to lock for access; NULL to lock the entire texture.</param>
        /// <param name="pixels">this is filled in with a pointer to the locked pixels, appropriately offset by the locked area.</param>
        /// <param name="pitch">this is filled in with the pitch of the locked pixels; the pitch is the length of one row in bytes.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false if the texture is not valid or was not created with <see cref="CSDL.Video.TextureAccess.Streaming">Streaming</see>; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_LockTexture">SDL_LockTexture</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Video.Texture.LockToSurface">LockToSurface</see></seealso>
        /// <seealso><see cref="CSDL.Video.Texture.Unlock">Unlock</see></seealso>
        public static extern void LockTexture();

        /// <summary>
        /// <para>Lock a portion of the texture for **write-only** pixel access, and expose it as a SDL surface.</para>
