        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_RenderDebugText">SDL_RenderDebugText</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Video.Renderer.RenderDebugTextFormat">RenderDebugTextFormat</see></seealso>
        /// <seealso><see cref="CSDL.Video.Macros.DebugTextFontCharacterSize">DebugTextFontCharacterSize</see></seealso>
        public static extern void RenderDebugText();

