        /// <seealso><see cref="CSDL.Video.Renderer(Window,string?)">Renderer(Window,string?)</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.Clear">Clear</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.RenderFillRect">RenderFillRect</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.RenderFillRects">RenderFillRects</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.RenderLine">RenderLine</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.RenderLineStrip">RenderLineStrip</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.RenderPoint">RenderPoint</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.Render">Render</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.RenderRect">RenderRect</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.RenderRects">RenderRects</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.DrawBlendMode">DrawBlendMode</see></seealso>
        /// <seealso><see cref="CSDL.Video.Renderer.DrawColor">DrawColor</see></seealso>
        public static extern void RenderPresent();

