        /// <param name="bottom_height">the height, in pixels, of the bottom corners in <c>srcrect</c>.</param>
        /// <param name="scale">the scale used to transform the corner of <c>srcrect</c> into the corner of <c>dstrect</c>, or 0.0f for an unscaled copy.</param>
