        /// </summary>
        /// <remarks>
        /// <para>**Warning**: Please note that <see cref="CSDL.Video.Texture.Lock">Lock</see> is intended to be write-only; it will not guarantee the previous contents of the texture will be provided. You must fully initialize any area of a texture that you lock before unlocking it, as the pixels might otherwise be uninitialized memory.</para>
        /// <para>Which is to say: locking and immediately unlocking a texture can result in corrupted textures, depending on the renderer in use.</para>
        /// </remarks>
        /// <param name="texture">a texture locked by <see cref="CSDL.Video.Texture.Lock">Lock</see>.</param>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UnlockTexture">SDL_UnlockTexture</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Video.Texture.Lock">Lock</see></seealso>
        public static extern void UnlockTexture();

        /// <summary>
        /// <para>Update a rectangle within a planar NV12 or NV21 texture with new pixels.</para>
        /// </summary>
        /// <remarks>
        /// <para>You can use <see cref="CSDL.Video.Texture.Update">Update</see> as long as your pixel data is a contiguous block of NV12/21 planes in the proper order, but this function is available if your pixel data is not contiguous.</para>
        /// </remarks>
        /// <param name="texture">the texture to update.</param>
        /// <param name="rect">a pointer to the rectangle of pixels to update, or NULL to update the entire texture.</param>
        /// <param name="Yplane">the raw pixel data for the Y plane.</param>
        /// <param name="Ypitch">the number of bytes between rows of pixel data for the Y plane.</param>
        /// <param name="UVplane">the raw pixel data for the UV plane.</param>
        /// <param name="UVpitch">the number of bytes between rows of pixel data for the UV plane.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UpdateNVTexture">SDL_UpdateNVTexture</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Video.Texture.Update">Update</see></seealso>
        /// <seealso><see cref="CSDL.Video.Texture.UpdateYUV">UpdateYUV</see></seealso>
        public static extern void UpdateNVTexture();

        /// <summary>
        /// <para>Update the given texture rectangle with new pixel data.</para>
        /// </summary>
        /// <remarks>
        /// <para>The pixel data must be in the pixel format of the texture, which can be queried using the <see cref="CSDL.Props.TextureFormatNumber">TextureFormatNumber</see> property.</para>
        /// <para>This is a fairly slow function, intended for use with static textures that do not change often.</para>
        /// <para>If the texture is intended to be updated often, it is preferred to create the texture as streaming and use the locking functions referenced below. While this function will work with streaming textures, for optimization reasons you may not get the pixels back if you lock the texture afterward.</para>
        /// </remarks>
        /// <param name="texture">the texture to update.</param>
        /// <param name="rect">an <see cref="CSDL.Video.Rect">Rect</see> structure representing the area to update, or NULL to update the entire texture.</param>
        /// <param name="pixels">the raw pixel data in the format of the texture.</param>
        /// <param name="pitch">the number of bytes in a row of pixel data, including padding between lines.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UpdateTexture">SDL_UpdateTexture</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Video.Texture.Lock">Lock</see></seealso>
        /// <seealso><see cref="CSDL.Video.Texture.Unlock">Unlock</see></seealso>
        /// <seealso><see cref="CSDL.Video.Texture.UpdateNV">UpdateNV</see></seealso>
        /// <seealso><see cref="CSDL.Video.Texture.UpdateYUV">UpdateYUV</see></seealso>
        public static extern void UpdateTexture();

        /// <summary>
        /// <para>Update a rectangle within a planar YV12 or IYUV texture with new pixel data.</para>
        /// </summary>
        /// <remarks>
        /// <para>You can use <see cref="CSDL.Video.Texture.Update">Update</see> as long as your pixel data is a contiguous block of Y and U/V planes in the proper order, but this function is available if your pixel data is not contiguous.</para>
        /// </remarks>
        /// <param name="texture">the texture to update.</param>
        /// <param name="rect">a pointer to the rectangle of pixels to update, or NULL to update the entire texture.</param>
        /// <param name="Yplane">the raw pixel data for the Y plane.</param>
        /// <param name="Ypitch">the number of bytes between rows of pixel data for the Y plane.</param>
        /// <param name="Uplane">the raw pixel data for the U plane.</param>
        /// <param name="Upitch">the number of bytes between rows of pixel data for the U plane.</param>
        /// <param name="Vplane">the raw pixel data for the V plane.</param>
        /// <param name="Vpitch">the number of bytes between rows of pixel data for the V plane.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UpdateYUVTexture">SDL_UpdateYUVTexture</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Video.Texture.UpdateNV">UpdateNV</see></seealso>
        /// <seealso><see cref="CSDL.Video.Texture.Update">Update</see></seealso>
        public static extern void UpdateYUVTexture();
    }
}
